import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353;
    static int m;
    static long[] prefix;

    // windowed sum of values over [j - d, j + d], kept only on holds of row
    static long[] transfer(long[] values, String row, long d) {
        prefix[0] = 0;
        for (int j = 0; j < m; j++) prefix[j + 1] = (prefix[j] + values[j]) % MOD;
        long[] res = new long[m];
        for (int j = 0; j < m; j++)
            if (row.charAt(j) == 'X') {
                int hi = (int) Math.min(m, j + d + 1), lo = (int) Math.max(0, j - d);
                res[j] = ((prefix[hi] - prefix[lo]) % MOD + MOD) % MOD;
            }
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in), 1 << 16);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        long w = Long.parseLong(st.nextToken());
        String[] g = new String[n];
        for (int i = 0; i < n; i++) {
            String line = br.readLine().trim();
            while (line.isEmpty()) line = br.readLine().trim();
            g[i] = line;
        }
        // largest horizontal offset allowed between adjacent rows: dx^2 + 1 <= w^2
        long radius = (long) Math.sqrt((double) (w * w - 1));
        while (radius * radius > w * w - 1) radius--;
        while ((radius + 1) * (radius + 1) <= w * w - 1) radius++;
        prefix = new long[m + 1];
        long[] incoming = new long[m], finished = null;
        for (int j = 0; j < m; j++) incoming[j] = g[n - 1].charAt(j) == 'X' ? 1 : 0;
        for (int i = n - 1; i >= 0; i--) {
            finished = transfer(incoming, g[i], w);
            if (i > 0) incoming = transfer(finished, g[i - 1], radius);
        }
        long total = 0;
        for (long v : finished) total = (total + v) % MOD;
        System.out.println(total);
    }
}

package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
)

const MOD = 998244353

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	var n, m, w int
	fmt.Fscan(in, &n, &m, &w)
	g := make([]string, n)
	for i := range g {
		fmt.Fscan(in, &g[i])
	}
	// largest horizontal offset allowed between adjacent rows: dx^2 + 1 <= w^2
	radius := int(math.Sqrt(float64(w*w - 1)))
	for radius*radius > w*w-1 {
		radius--
	}
	for (radius+1)*(radius+1) <= w*w-1 {
		radius++
	}
	prefix := make([]int, m+1)
	// windowed sum of values over [j - d, j + d], kept only on holds of row
	transfer := func(values []int, row string, d int) []int {
		for j := 0; j < m; j++ {
			prefix[j+1] = (prefix[j] + values[j]) % MOD
		}
		res := make([]int, m)
		for j := 0; j < m; j++ {
			if row[j] == 'X' {
				hi, lo := min(m, j+d+1), max(0, j-d)
				res[j] = ((prefix[hi]-prefix[lo])%MOD + MOD) % MOD
			}
		}
		return res
	}
	incoming := make([]int, m)
	for j := 0; j < m; j++ {
		if g[n-1][j] == 'X' {
			incoming[j] = 1
		}
	}
	var finished []int
	for i := n - 1; i >= 0; i-- {
		finished = transfer(incoming, g[i], w)
		if i > 0 {
			incoming = transfer(finished, g[i-1], radius)
		}
	}
	total := 0
	for _, v := range finished {
		total = (total + v) % MOD
	}
	fmt.Println(total)
}
